CREATE POLICY "documents_read_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'documents' AND owner = auth.uid());
CREATE POLICY "documents_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'documents' AND owner = auth.uid());
CREATE POLICY "documents_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'documents' AND owner = auth.uid()) WITH CHECK (bucket_id = 'documents' AND owner = auth.uid());
CREATE POLICY "documents_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'documents' AND owner = auth.uid());